const sample = {
  "demo": true,
  "period": "2026-W47",
  "rows": [
    {
      "impressions": 12000,
      "clicks": 340,
      "follows": 28
    }
  ],
  "previous": {
    "impressions": 10000,
    "clicks": 300,
    "follows": 20
  }
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const rows = Array.isArray(item.rows) ? item.rows : [item];
const keys = ['impressions', 'clicks', 'follows'];
const totals = {};
for (const key of keys) totals[key] = 0;
for (const row of rows) {
  for (const key of keys) totals[key] += Number(row[key] || 0);
}
const previous = item.previous || {};
const deltas = {};
for (const key of keys) {
  const before = Number(previous[key] || 0);
  deltas[key] = before === 0 ? null : Math.round(((totals[key] - before) / before) * 1000) / 10;
}
const lines = keys.map((key) => key + ': ' + totals[key] + (deltas[key] === null ? '' : ' (' + (deltas[key] > 0 ? '+' : '') + deltas[key] + '%)'));
const record = { report: 'Social week', period: item.period || 'last-7-days', totals, deltas, narrative: lines.join('\n') };
return {
  summary: 'Social week' + ' for ' + record.period + '. ' + lines[0] + '.',
  route: 'send',
  record,
  slackText: 'Social week' + '\n' + lines.join('\n'),
  actions: [{ app: 'Slack', operation: 'post', payload: record }],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'weekly-social-performance',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
